import {useLayoutEffect,useMemo,useRef,type ComponentRef} from 'react';
import {FlatList,Pressable,Text,View,type ViewProps} from 'react-native';
import {Button} from '@/components/nyc-tron/ui/components/Button';
import {ErrorMessage} from '@/components/nyc-tron/ui/components/feedback/ErrorMessage';
import {useOwnedAction} from '@/components/nyc-tron/ui/components/shell/useOwnedAction';
import {joinClasses} from '@/components/nyc-tron/ui/components/styles';
import {compositionAncestors,flattenCompositionLayers,validateCompositionLayers,type CompositionLayer,type CompositionTreeRow} from '@/components/nyc-tron/ui/components/forge/motion/composition-tree';
export type {CompositionLayer,CompositionLayerKind} from '@/components/nyc-tron/ui/components/forge/motion/composition-tree';
export interface CompositionLayerTreeProps extends Omit<ViewProps,'children'> {
 readonly scope:string;readonly revision?:string|number;readonly compositionId:string;readonly layers:readonly CompositionLayer[];readonly expandedIds:readonly string[];readonly selectedId:string|null;
 readonly onExpandedChange:(ids:readonly string[])=>void;readonly onSelect:(id:string)=>void;
 readonly onVisibilityChange:(id:string,visible:boolean,signal:AbortSignal)=>void|Promise<void>;
 readonly height?:number;readonly disabled?:boolean;readonly unstyled?:boolean;
}
const ROW=92;
/** Virtualized nested composition/shape/text/footage/adjustment hierarchy with stable layer identity. */
export function CompositionLayerTree({scope,revision=0,compositionId,layers,expandedIds,selectedId,onExpandedChange,onSelect,onVisibilityChange,height=320,disabled=false,unstyled=false,...props}:CompositionLayerTreeProps){
 useMemo(()=>validateCompositionLayers(layers,compositionId),[layers,compositionId]);if(!scope.trim()||!Number.isFinite(height)||height<100||height>4000||new Set(expandedIds).size!==expandedIds.length)throw new RangeError('Invalid composition tree scope, expansion or viewport');
 const action=useOwnedAction(JSON.stringify([scope,compositionId,revision])),pending=action.pending!==null,rows=useMemo(()=>flattenCompositionLayers(layers,expandedIds),[layers,expandedIds]);
 const list=useRef<ComponentRef<typeof FlatList<CompositionTreeRow>>|null>(null),reveal=useRef<string|null>(null);
 useLayoutEffect(()=>{if(!reveal.current)return;const index=rows.findIndex(row=>row.layer.id===reveal.current);if(index<0)return;reveal.current=null;list.current?.scrollToIndex({index,animated:false});},[rows]);
 const expand=(id:string)=>{if(disabled)return;onExpandedChange(expandedIds.includes(id)?expandedIds.filter(value=>value!==id):[...expandedIds,id]);};
 const revealSelected=()=>{if(disabled||!selectedId||!layers.some(layer=>layer.id===selectedId))return;reveal.current=selectedId;const next=[...new Set([...expandedIds,...compositionAncestors(layers,selectedId)])];onExpandedChange(next);const index=rows.findIndex(row=>row.layer.id===selectedId);if(index>=0){reveal.current=null;list.current?.scrollToIndex({index,animated:false});}};
 return <View {...props} style={[{gap:8},props.style]}>
  <Button title="Reveal selected composition layer" disabled={disabled||!selectedId||!layers.some(layer=>layer.id===selectedId)} unstyled={unstyled} onPress={revealSelected}/>
  <FlatList ref={list} data={rows} keyExtractor={row=>row.layer.id} style={{height}} initialNumToRender={8} windowSize={5} getItemLayout={(_,index)=>({length:ROW,offset:ROW*index,index})} extraData={[selectedId,expandedIds,pending,disabled]} accessibilityLabel="Composition layer tree"
   ListEmptyComponent={<Text {...{className:joinClasses(!unstyled&&'text-text-muted')}}>This composition has no layers</Text>}
   renderItem={({item})=>{const layer=item.layer,expanded=expandedIds.includes(layer.id);return <View style={{height:ROW,paddingLeft:Math.min(item.depth,6)*12,flexDirection:'row',alignItems:'center',gap:4}}>
    {layer.kind==='composition'?<Button title={expanded?'−':'+'} accessibilityLabel={`${expanded?'Collapse':'Expand'} ${layer.name}`} disabled={disabled||!item.hasChildren} unstyled={unstyled} onPress={()=>expand(layer.id)}/>:<View style={{width:44}}/>}
    <Pressable accessibilityRole="button" accessibilityLabel={`Select ${layer.name}, ${layer.kind}, level ${item.depth+1}${layer.locked?', locked':''}`} accessibilityState={{selected:layer.id===selectedId,disabled}} disabled={disabled} onPress={()=>{if(!disabled)onSelect(layer.id);}} style={{flex:1,minWidth:44,minHeight:60,justifyContent:'center',gap:2}}>
     <Text numberOfLines={2} {...{className:joinClasses(!unstyled&&'text-text')}}>{layer.name}</Text><Text numberOfLines={1} {...{className:joinClasses(!unstyled&&'text-text-muted')}}>{`${layer.kind} · ${Math.round(layer.opacity*100)}%${layer.locked?' · locked':''}`}</Text>
    </Pressable>
    <Button title={layer.visible?'Hide':'Show'} accessibilityLabel={`${layer.visible?'Hide':'Show'} ${layer.name}`} disabled={disabled||pending} unstyled={unstyled} onPress={()=>{if(!disabled&&!pending)void action.run(layer.id,signal=>onVisibilityChange(layer.id,!layer.visible,signal));}}/>
   </View>;}}/>
  {pending?<Button title="Cancel layer visibility request" unstyled={unstyled} onPress={action.cancel}/>:null}
  <ErrorMessage {...(action.error?{message:action.error}:{})} unstyled={unstyled}/>
 </View>;
}

import { createStore } from "zustand/vanilla";

/** UI request state. Abort controllers stay in the owner's closure. */
export interface ActionState { readonly pending: string | null; readonly error: string | null }
export function createActionOwner(currentScope: () => string) {
  const store = createStore<ActionState>(() => ({ pending: null, error: null }));
  let active = false;
  let current: { readonly scope: string; readonly abort: AbortController } | null = null;
  function cancel() {
    const previous = current; current = null;
    previous?.abort.abort();
  }
  return {
    store,
    activate() { cancel(); active = true; store.setState({ pending: null, error: null }); },
    deactivate() { active = false; cancel(); },
    cancel() { cancel(); store.setState({ pending: null }); },
    async run<T>(id: string, operation: (signal: AbortSignal) => T | Promise<T>, consume?: (value: T) => void, options?: { pendingForAsyncOnly?: boolean }): Promise<boolean> {
      if (!active) return false;
      cancel();
      const request = { scope: currentScope(), abort: new AbortController() };
      current = request;
      const valid = () => active && current === request && request.scope === currentScope();
      if (options?.pendingForAsyncOnly) store.setState({ error: null });
      else store.setState({ pending: id, error: null });
      try {
        if (!valid()) return false;
        const result = operation(request.abort.signal);
        let value: T;
        if (options?.pendingForAsyncOnly) {
          if (result && typeof (result as Promise<T>).then === 'function') {
            // A synchronous acknowledgement or already-resolved promise must not
            // disable (and blur) the focused control between keyboard commands.
            let settled = false;
            const completion = Promise.resolve(result).then(value => { settled = true; return value; }, error => { settled = true; throw error; });
            void Promise.resolve().then(() => { if (!settled && valid()) store.setState({ pending: id, error: null }); });
            value = await completion;
          } else value = result as T;
        } else value = await result;
        if (!valid()) return false;
        consume?.(value);
        if (!valid()) return false;
        store.setState({ pending: null });
        return true;
      } catch (error) {
        if (!valid()) return false;
        store.setState({ pending: null, error: error instanceof Error ? error.message : String(error) });
        return false;
      } finally { if (current === request) current = null; }
    },
  };
}

import { useLayoutEffect, useRef } from "react";
import { useStore } from "zustand";
import { createActionOwner } from "@/components/nyc-tron/ui/components/shell/action-owner";

/** Cancel stale requests at the committed document boundary, before new controls accept input. */
export function useOwnedAction(scope: string) {
  const committed = useRef(scope);
  const ref = useRef<ReturnType<typeof createActionOwner> | null>(null);
  ref.current ??= createActionOwner(() => committed.current);
  const owner = ref.current;
  useLayoutEffect(() => {
    committed.current = scope;
    owner.activate();
    return () => owner.deactivate();
  }, [owner, scope]);
  const state = useStore(owner.store, value => value);
  const run: typeof owner.run = (id, operation, consume, options) => committed.current === scope ? owner.run(id, operation, consume, options) : Promise.resolve(false);
  return { ...state, run, cancel: owner.cancel };
}

/**
 * Tailwind classes are merged at the APP boundary. Joining without
 * tailwind-merge avoids deleting custom typography/color utilities that
 * depend on each consumer's own @theme configuration.
 */
export function joinClasses(...items: Array<string|false|null|undefined>):string {
  return items.filter(Boolean).join(" ");
}
